// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, address actor) public {
        vm.assume(putAmount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        putAmount = bound(putAmount, c.MinSum(), 100 ether);
        collectAmount = bound(collectAmount, c.MinSum(), putAmount);

        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(0);

        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(actor);
        vm.assume(balanceBefore >= c.MinSum());

        vm.warp(unlockTime + 1);

        uint256 cBalanceBefore = address(c).balance;

        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 cBalanceAfter = address(c).balance;

        // If Collect succeeded in paying out, the recorded Acc balance must also drop by the amount.
        if (cBalanceAfter == cBalanceBefore - collectAmount) {
            (, uint256 balanceAfter) = c.Acc(actor);
            assertTrue(balanceAfter == balanceBefore - collectAmount);
        } else {
            // Collect did not succeed in this admissible environment; nothing to check.
            assertTrue(true);
        }
    }
}
